        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("isValidIPv4(192.168.0.1)", Boolean.TRUE, valid("192.168.0.1"));
        check("isValidIPv4(0.0.0.0) -- a single zero is allowed", Boolean.TRUE, valid("0.0.0.0"));
        check("isValidIPv4(256.1.1.1) -- over 255", Boolean.FALSE, valid("256.1.1.1"));
        check("isValidIPv4(192.168.01.1) -- leading zero", Boolean.FALSE, valid("192.168.01.1"));
        check("isValidIPv4(10.0.0) -- only three parts", Boolean.FALSE, valid("10.0.0"));
